pr, pv = rs.dump(b'__x'), vs.dump(b'__x')
rs.delete(b'__x'); vs.delete(b'__x')
M = 0xFFFFFFFFFFFFFFFF

def crc_msb(data, poly, init=0, xorout=0):
    c = init
    for b in data:
        c ^= (b << 56)
        for _ in range(8):
            c = ((c << 1) ^ poly) & M if (c & (1 << 63)) else (c << 1) & M
    return c ^ xorout

def crc_lsb(data, poly, init=0, xorout=0):
    c = init
    for b in data:
        c ^= b
        for _ in range(8):
            c = ((c >> 1) ^ poly) if (c & 1) else (c >> 1)
    return c ^ xorout

tests = [
 ('MSB ECMA poly 42F0..', crc_msb, 0x42F0E1EBA9EA3693),
 ('LSB refl C96C..', crc_lsb, 0xC96C5795D7870F42),
]
for name, p in (('redis', pr), ('valkey', pv)):
    body, want = p[:-8], p[-8:]
    hits = []
    for tn, fn, poly in tests:
        for inlabel, data in (('body', body), ('body+z8', body + b'\x00'*8)):
            for ini in (0, M):
                for xo in (0, M):
                    c = fn(data, poly, ini, xo)
                    for en, pack in (('LE', struct.pack('<Q', c)), ('BE', struct.pack('>Q', c))):
                        if pack == want:
                            hits.append((tn, inlabel, hex(ini), hex(xo), en))
    print(f'{name} hits: {hits}')
    print(f'  {name} stored ck: {want.hex()}')
