M64 = 0xFFFFFFFFFFFFFFFF
POLY = 0xad93d23594c935a9
def reflect64(v):
    r = 0
    for i in range(64):
        r = (r << 1) | ((v >> i) & 1)
    return r
def crc64raw(crc, data):
    for c in data:
        for i in range(8):
            bit = (crc >> 63) & 1
            if c & (1 << i):
                bit ^= 1
            crc = (crc << 1) & M64
            if bit:
                crc ^= POLY
    return reflect64(crc)

for name, p in (('valkey', pv), ('redis', pr)):
    body, stored = p[:-8], p[-8:]
    for init in (0, M64):
        c = crc64raw(init, body)
        if struct.pack('<Q', c) == stored:
            print(f'{name}: MATCH with init={hex(init)} -> {struct.pack("<Q",c).hex()}')
        elif init == 0:
            print(f'{name}: init=0 gave {struct.pack("<Q",c).hex()}, stored {stored.hex()}')
