rs = redis.Redis(port=6379, db=0)
r = redis.Redis(port=6379, db=2)
affected = {}
for db, keys in ((0, [l.split()[1] for l in open('/tmp/types_db0.txt') if l.startswith('hash')]),
                 (2, [k.decode() for k in r.scan_iter() if r.type(k) == b'hash'])):
